import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"Quantum Mechanics — Superposition & Observation","description":"","frontmatter":{},"headers":[],"relativePath":"docs/science/quantum.md","filePath":"docs/science/quantum.md"}`),a={name:`docs/science/quantum.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="quantum-mechanics-—-superposition-observation" tabindex="-1">Quantum Mechanics — Superposition &amp; Observation <a class="header-anchor" href="#quantum-mechanics-—-superposition-observation" aria-label="Permalink to “Quantum Mechanics — Superposition &amp; Observation”">​</a></h1><h2 id="the-sealed-truth" tabindex="-1">The Sealed Truth <a class="header-anchor" href="#the-sealed-truth" aria-label="Permalink to “The Sealed Truth”">​</a></h2><p><strong>Theorem:</strong> <code>Quantum.lean</code> (42 theorems, all <code>by decide</code>)</p><p>The Born rule: probability = |amplitude|². Superposition is real until measured. No-signaling: you cannot use entanglement to send messages faster than <em>c</em>. GHZ states prove non-locality. The Pauli matrices square to identity. Clifford gates preserve the Witt form.</p><p><strong>Why sealed:</strong> Pure linear algebra over ℤ[i, 1/√2]. Exact Gaussian integers, no decimal drift.</p><hr><h2 id="the-metaphysical-pair" tabindex="-1">The Metaphysical Pair <a class="header-anchor" href="#the-metaphysical-pair" aria-label="Permalink to “The Metaphysical Pair”">​</a></h2><p><strong>The Question:</strong> <em>Does observation create reality, or does reality create observers?</em></p><table tabindex="0"><thead><tr><th>Perspective</th><th>What It Proves</th><th>What It Cannot</th></tr></thead><tbody><tr><td><strong>Decidable (Sealed)</strong></td><td>Measurement outcomes are probabilistic by Born rule. Entanglement is non-local (correlations faster than light, but no FTL signaling). The state is a superposition until measurement.</td><td>Whether measurement &quot;causes&quot; collapse or just reveals pre-existing values; whether reality is deterministic underneath; whether consciousness plays a role</td></tr><tr><td><strong>Honest Boundary</strong></td><td>Quantum mechanics predicts experimental outcomes exactly. The philosophy of what it &quot;means&quot; is open. Copenhagen, Many-Worlds, Pilot-Wave all predict identically.</td><td>Which interpretation is true; whether the wave function is real or epistemic; whether the universe is determinate or fundamentally random</td></tr><tr><td><strong>Metaphysical</strong></td><td>If the act of observation determines the outcome (Copenhagen) vs. all outcomes happen in parallel (Many-Worlds), which is true? Does your choice of what to measure create which reality exists?</td><td>Whether free will is possible in quantum mechanics; whether consciousness is fundamental; whether the universe is participatory</td></tr></tbody></table><p><strong>The court decides:</strong> Quantum mechanics seals the math. Philosophy settles the interpretation.</p><hr><h2 id="read-the-sealed-proofs" tabindex="-1">Read the Sealed Proofs <a class="header-anchor" href="#read-the-sealed-proofs" aria-label="Permalink to “Read the Sealed Proofs”">​</a></h2><p><a href="./../../lean/Quantum.lean">Quantum.lean</a> — 42 theorems: Born rule, no-signaling, GHZ, Clifford gates, phase algebra</p><p>Each proven <code>by decide</code>.</p><hr><h2 id="the-research-question" tabindex="-1">The Research Question <a class="header-anchor" href="#the-research-question" aria-label="Permalink to “The Research Question”">​</a></h2><p>If measurement creates superposition collapse, and consciousness is what measures, then:</p><ol><li>Is consciousness fundamental to physics?</li><li>Do multiple observers create multiple realities?</li><li>Is free will guaranteed by quantum indeterminacy?</li></ol><p><strong>These are open.</strong> Quantum mechanics does not answer them. Philosophy and neuroscience must.</p>`,19)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};